    pieces: art, hitbox: hb0 ? { ...hb0, x: hb0.x + dx, y: hb0.y + dy } : null,
    wPx: Math.max(4, box.w * unit), hPx: Math.max(4, box.h * unit),
    canvasWPx: W * unit, canvasHPx: H * unit,
