    colors: [["base", "Ground", "#3b1d6e"], ["r1", "Ring 1", "#1f6fd0"], ["r2", "Ring 2", "#12a86e"], ["r3", "Ring 3", "#e8c11c"], ["r4", "Centre", "#d4306b"]],
    // Crinkle 0 = neat concentric circles (a bullseye tie). 1 = heavily scrunched, rings barely
