export const CAMERA_EASE = 0.14;       // fraction of the remaining distance the camera closes each frame (at 60fps)
const CONN_SIDE = { N1: "N", N2: "N", E1: "E", E2: "E", S1: "S", S2: "S", W1: "W", W2: "W" };
