export const SCORE_LEVEL_CLEAR = 500;
export const SCORE_PAR_SECS = 30;
export const SCORE_LOSS_PER_SEC = 10;
export const newScoreState = () => ({ total: 0, secs: {}, cleared: {}, spent: {} });
