                  const hpNowMs = performance.now();
                  const hpHot = noteUnitHp(U.hpSeen, uKey, curHp, hpNowMs);
                  const hpBarA = unitHpBarAlpha(U.hpSeen, uKey, hpNowMs); // only just after a hit
